#include <string.h>
#include "test_env.h"

#if defined(N7S_TARGET_SAMV71Q21)
#include <stdint.h>
#include <rtems/sysinit.h>

/*
 * SAMV71 flash wait states.
 * This project runs the code from the internal flash (linkcmds.samv71.intflash),
 * but the TASTE runtime (SamV71Core_Init, called by the Init task) raises the
 * clock to 300 MHz core / 150 MHz MCK without programming the flash wait
 * states, as it normally runs the code from SRAM. At 150 MHz the flash needs
 * 7 access cycles (FWS = 6, SAMV71 datasheet): set them at the start of the
 * RTEMS system initialization, while the chip still runs on its reset clock.
 * This is in test_env.c because a source file containing only this hook
 * would not be linked: nothing references it.
 */
#define EEFC_FMR (*(volatile uint32_t *)0x400E0C00U)   // EEFC Flash Mode Register
#define EEFC_FMR_FWS_SHIFT 8U
#define EEFC_FMR_FWS_MASK (0xFU << EEFC_FMR_FWS_SHIFT)
#define FLASH_WAIT_STATES 6U

static void set_flash_wait_states(void)
{
   EEFC_FMR = (EEFC_FMR & ~EEFC_FMR_FWS_MASK) | (FLASH_WAIT_STATES << EEFC_FMR_FWS_SHIFT);
   __asm__ volatile ("dsb\n\tisb" ::: "memory");
}

RTEMS_SYSINIT_ITEM(set_flash_wait_states, RTEMS_SYSINIT_BSP_EARLY, RTEMS_SYSINIT_ORDER_FIRST);
#endif

/*
 * Test driver for JpegCompressor on SAMRH71 / SAMV71 (RTEMS), without any
 * console output: the results are kept in test_results[] and the counters
 * below, to be read with the debugger once test_finished is set.
 *
 * Scenarios run one after the other: a scenario uploads its generated 64x64
 * image and calls start_compression; the next trigger after
 * compression_completed checks the result, downloads the compressed data
 * and starts the next scenario.
 * The CRC-32 of each lossless codestream is compared with expected_crc32,
 * obtained by running the same scenario on Linux (the lossless codestreams
 * are identical on the boards, verified on SAMRH71). These references must
 * be updated when the compressor, its configuration or the test images
 * change.
 * For each compression the encoder pool high-water mark (the pool size really
 * needed) is recorded next to the peak of memory in use: the difference is
 * the memory lost to fragmentation, the worst case is kept in
 * test_worst_fragmentation_permille.
 */

extern size_t jpegcompressor_get_memory_high_water(void);

#define IMAGE_SIZE 64U
#define MAX_IMAGE_SIZE (IMAGE_SIZE * IMAGE_SIZE * 2U)   // 1 component, 16 bits

typedef enum { PATTERN_SMOOTH, PATTERN_NOISE } pattern_t;

typedef struct {
   const char *name;
   asn1SccJpeg_Compression_Config config;
   pattern_t pattern;
   unsigned upload_size;            // 0: whole image, otherwise number of bytes uploaded
   asn1SccJpeg_Result_Code expected;
   unsigned long expected_crc32;    // reference codestream CRC-32, 0: not checked (lossy, errors)
} scenario_t;

typedef struct {
   asn1SccJpeg_Result_Code result;  // compression result
   unsigned output_size;            // compressed size in bytes
   unsigned long crc32;             // CRC-32 of the downloaded codestream
   unsigned long memory_peak;       // encoder pool peak usage in bytes
   unsigned long memory_high_water; // pool size really needed: peak + fragmentation
   const char *failure;             // first failed check, NULL if the scenario passed
} test_result_t;

#define CONFIG(depth, is_signed, ratio, res, tile) \
   { IMAGE_SIZE, IMAGE_SIZE, 1, (depth), (is_signed), (ratio), (res), (tile) }

static const scenario_t scenarios[] = {
   { "gray8_lossless",        CONFIG(8, 0, 0, 6, 0),   PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0x9beb3c54UL },
   { "gray8_lossless_tiled",  CONFIG(8, 0, 0, 5, 32),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0x4d65c91aUL },
   { "gray8_lossless_res3",   CONFIG(8, 0, 0, 3, 0),   PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0x0492c33aUL },
   { "gray8_signed_lossless", CONFIG(8, 1, 0, 6, 0),   PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0xa4f4a007UL },
   { "gray8_lossy10",         CONFIG(8, 0, 10, 6, 0),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0UL },
   { "gray12_lossless",       CONFIG(12, 0, 0, 6, 0),  PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0x9f413605UL },
   { "gray16_lossless_noise", CONFIG(16, 0, 0, 6, 0),  PATTERN_NOISE,  0, Jpeg_Result_Code_ok, 0xa1215a30UL },
   { "gray16_lossy20",        CONFIG(16, 0, 20, 6, 0), PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0UL },
   { "err_partial_upload",    CONFIG(8, 0, 0, 6, 0),   PATTERN_SMOOTH, 1000, Jpeg_Result_Code_input_size_mismatch, 0UL },
   { "err_too_many_levels",   CONFIG(8, 0, 0, 8, 0),   PATTERN_SMOOTH, 0, Jpeg_Result_Code_invalid_config, 0UL },
   { "gray8_after_errors",    CONFIG(8, 0, 0, 6, 0),   PATTERN_SMOOTH, 0, Jpeg_Result_Code_ok, 0x9beb3c54UL },
};
#define SCENARIO_COUNT (sizeof(scenarios) / sizeof(scenarios[0]))

// Results, to be read with the debugger
volatile test_result_t test_results[SCENARIO_COUNT];
volatile unsigned test_scenarios_done;
volatile unsigned test_failures;
volatile int test_finished;
// Worst pool fragmentation: memory lost, in 1/1000 of the peak, and the index
// of its scenario in test_results[]
volatile unsigned long test_worst_fragmentation_permille;
volatile unsigned test_worst_fragmentation_scenario;

static unsigned char image[MAX_IMAGE_SIZE];

// Interface parameters, kept static to keep them off the small thread stacks
// (the write request and the data chunk are ~1 KB each)
static asn1SccJpeg_Write_Request write_request;
static asn1SccJpeg_Read_Request read_request;
static asn1SccJpeg_Data_Chunk chunk;
static asn1SccJpeg_Compressor_Status status;

static unsigned current;
static int waiting;
static int completed;
static asn1SccJpeg_Compression_Result completion;

static void fail(const char *what)
{
   if (test_results[current].failure == NULL) {
      test_results[current].failure = what;
      test_failures++;
   }
}

static unsigned image_size(const asn1SccJpeg_Compression_Config *c)
{
   return (unsigned)(c->width * c->height * c->num_components * (c->bit_depth <= 8 ? 1 : 2));
}

// CRC-32 (IEEE 802.3), updated chunk by chunk: crc must start at 0
static unsigned long crc32_update(unsigned long crc, const unsigned char *data, unsigned size)
{
   unsigned i;
   int bit;

   crc ^= 0xFFFFFFFFUL;
   for (i = 0; i < size; i++) {
      crc ^= data[i];
      for (bit = 0; bit < 8; bit++) {
         crc = (crc >> 1) ^ (0xEDB88320UL & (0UL - (crc & 1UL)));
      }
   }
   return crc ^ 0xFFFFFFFFUL;
}

static void generate_image(const scenario_t *s)
{
   const asn1SccJpeg_Compression_Config *c = &s->config;
   unsigned bytes = c->bit_depth <= 8 ? 1U : 2U;
   unsigned max = (1U << c->bit_depth) - 1U;
   unsigned seed = 12345U;
   unsigned i = 0;
   unsigned comp, x, y;

   for (comp = 0; comp < c->num_components; comp++) {
      for (y = 0; y < c->height; y++) {
         for (x = 0; x < c->width; x++) {
            unsigned v;
            seed ^= seed << 13; // xorshift32
            seed ^= seed >> 17;
            seed ^= seed << 5;
            if (s->pattern == PATTERN_NOISE) {
               v = (seed >> 16) & max;
            } else {
               v = ((x * 7U + y * 3U + comp * 80U) * (max + 1U) / 1024U + ((seed >> 16) & 3U)) & max;
            }
            image[i++] = (unsigned char)(v & 0xFFU);
            if (bytes == 2U) {
               image[i++] = (unsigned char)(v >> 8);
            }
         }
      }
   }
}

static void upload(unsigned offset, unsigned size, asn1SccJpeg_Result_Code *result)
{
   unsigned length = size - offset < sizeof(write_request.data.arr) ? size - offset
                                                                    : (unsigned)sizeof(write_request.data.arr);
   write_request.offset = offset;
   write_request.data.nCount = (int)length;
   memcpy(write_request.data.arr, image + offset, length);
   test_env_RI_write_buffer(&write_request, result);
}

// Returns 1 when the compression was started, 0 if the scenario failed before
static int start_scenario(const scenario_t *s)
{
   asn1SccJpeg_Result_Code result;
   unsigned size = s->upload_size ? s->upload_size : image_size(&s->config);
   unsigned offset;

   if (image_size(&s->config) > MAX_IMAGE_SIZE) {
      fail("image larger than the test buffer");
      return 0;
   }
   generate_image(s);
   test_env_RI_clear_buffer(&result);
   if (result != Jpeg_Result_Code_ok) {
      fail("clear_buffer");
   }
   // Nothing to read after a clear
   read_request.offset = 0;
   read_request.length = 16;
   test_env_RI_read_buffer(&read_request, &chunk, &result);
   if (result != Jpeg_Result_Code_no_output || chunk.nCount != 0) {
      fail("read_buffer after clear should return no-output");
   }
   // A chunk leaving a gap must be refused
   if (size > sizeof(write_request.data.arr)) {
      upload((unsigned)sizeof(write_request.data.arr), size, &result);
      if (result != Jpeg_Result_Code_invalid_offset) {
         fail("write_buffer leaving a gap should return invalid-offset");
      }
   }
   // Upload in order, re-sending the first chunk once (retransmission)
   for (offset = 0; offset < size; offset += sizeof(write_request.data.arr)) {
      upload(offset, size, &result);
      if (result == Jpeg_Result_Code_ok && offset == sizeof(write_request.data.arr)) {
         upload(0, size, &result);
      }
      if (result != Jpeg_Result_Code_ok) {
         fail("write_buffer");
         return 0;
      }
   }
   waiting = 1;
   completed = 0;
   test_env_RI_start_compression(&s->config);
   return 1;
}

static void finish_scenario(const scenario_t *s)
{
   volatile test_result_t *r = &test_results[current];
   asn1SccJpeg_Result_Code result;
   unsigned long crc = 0UL;
   unsigned offset = 0;

   test_env_RI_status(&status);
   r->result = completion.result;
   r->output_size = (unsigned)completion.output_size;
   r->memory_peak = (unsigned long)status.memory_peak;
   r->memory_high_water = (unsigned long)jpegcompressor_get_memory_high_water();
   if (r->memory_peak > 0UL) {
      const unsigned long fragmentation_permille =
         ((r->memory_high_water - r->memory_peak) * 1000UL) / r->memory_peak;
      if (fragmentation_permille > test_worst_fragmentation_permille) {
         test_worst_fragmentation_permille = fragmentation_permille;
         test_worst_fragmentation_scenario = current;
      }
   }

   if (completion.result != s->expected) {
      fail("unexpected compression result");
      return;
   }
   if (status.last_result != completion.result ||
       status.state != (s->expected == Jpeg_Result_Code_ok ? Jpeg_Compressor_State_completed
                                                            : Jpeg_Compressor_State_failed)) {
      fail("status does not match the completion");
      return;
   }
   if (s->expected != Jpeg_Result_Code_ok) {
      return;
   }
   // Download in 1000-byte requests (not a multiple of the 1024-byte chunk)
   // to exercise partial chunks
   do {
      read_request.offset = offset;
      read_request.length = 1000;
      test_env_RI_read_buffer(&read_request, &chunk, &result);
      if (result != Jpeg_Result_Code_ok) {
         fail("read_buffer");
         return;
      }
      crc = crc32_update(crc, chunk.arr, (unsigned)chunk.nCount);
      offset += (unsigned)chunk.nCount;
   } while (chunk.nCount > 0);
   r->crc32 = crc;

   if (offset != completion.output_size || offset != status.output_size) {
      fail("downloaded size mismatch");
   }
   if (s->expected_crc32 != 0UL && crc != s->expected_crc32) {
      fail("codestream differs from the Linux reference");
   }
   read_request.offset = offset + 1U;
   test_env_RI_read_buffer(&read_request, &chunk, &result);
   if (result != Jpeg_Result_Code_invalid_offset) {
      fail("read past the end should return invalid-offset");
   }
}

void test_env_startup(void)
{
   current = 0;
   waiting = 0;
   test_scenarios_done = 0;
   test_failures = 0;
   test_finished = 0;
   test_worst_fragmentation_permille = 0UL;
   test_worst_fragmentation_scenario = 0U;
}

void test_env_PI_compression_completed( const asn1SccJpeg_Compression_Result *IN_result )
{
   completion = *IN_result;
   completed = 1;
}


void test_env_PI_trigger( void )
{
   while (current < SCENARIO_COUNT) {
      if (waiting) {
         if (!completed) {
            return;
         }
         waiting = 0;
         finish_scenario(&scenarios[current]);
         current++;
         test_scenarios_done = current;
      } else if (start_scenario(&scenarios[current])) {
         return; // wait for compression_completed
      } else {
         current++; // could not start, failure already counted
         test_scenarios_done = current;
      }
   }
   test_finished = 1;
}
